script:
var names = { "Claude bridge test": 1, "Claude test": 1, "Background": 1, "Solids": 1 };
var targets = [];
for (var i = 1; i <= app.project.numItems; i++) {
  var it = app.project.item(i);
  var isTestPng = it.name.indexOf("frame-") === 0 && it.parentFolder.name === "Claude test";
  if (names[it.name] || isTestPng) targets.push(it);
}
var removed = [];
for (var j = 0; j < targets.length; j++) {
  try { var n = targets[j].name; targets[j].remove(); removed.push(n); } catch (e) { /* already gone with its folder */ }
}
return { removed: removed, itemsLeft: app.project.numItems };
